// CFPS -> CodeForcesProblemSet
public final class CFPS {
    static FastReader fr = new FastReader();
    static PrintWriter out = new PrintWriter(System.out);
    static final int gigamod = 1000000007;
    static int t = 1;
    static double epsilon = 0.00000001;
    static boolean[] isPrime;
    static int[] smallestFactorOf;

    public static void main(String[] args) {
        for (int caseIdx = 0; caseIdx < t; caseIdx++) {
            char[] sOG = fr.next().toCharArray();
            int n = sOG.length;

            if (n == 1) {
                if (sOG[0] == '0' || sOG[0] == '_' || sOG[0] == 'X')
                    out.println(1);
                else
                    out.println(0);
                continue;
            }

            int totalWays = 0;

            // Check for "00" pattern
            {
                char[] s = sOG.clone();
                boolean invalid = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '0');
                invalid |= (s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '0');

                if (!invalid) {
                    if (s[n - 1] == 'X' || s[n - 2] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '0';
                    }
                    s[n - 1] = '0';
                    s[n - 2] = '0';

                    totalWays += check("00".toCharArray(), s);
                    for (int num = 0; num < 1000000; num++) {
                        char[] tgt = (Integer.toString(num) + "00").toCharArray();
                        totalWays += check(tgt, s);
                    }
                }
            }

            // Check for "25" pattern
            {
                char[] s = sOG.clone();
                boolean invalid = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '5');
                invalid |= s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '2';
                invalid |= (s[n - 1] == 'X' && s[n - 2] == 'X');

                if (!invalid) {
                    if (s[n - 1] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '5';
                    } else if (s[n - 2] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '2';
                    }
                    s[n - 1] = '5';
                    s[n - 2] = '2';

                    totalWays += check("25".toCharArray(), s);
                    for (int num = 0; num < 1000000; num++) {
                        char[] tgt = (Integer.toString(num) + "25").toCharArray();
                        totalWays += check(tgt, s);
                    }
                }
            }

            // Check for "50" pattern
            {
                char[] s = sOG.clone();
                boolean invalid = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '0');
                invalid |= s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '5';
                invalid |= (s[n - 1] == 'X' && s[n - 2] == 'X');

                if (!invalid) {
                    if (s[n - 1] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '0';
                    } else if (s[n - 2] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '5';
                    }
                    s[n - 1] = '0';
                    s[n - 2] = '5';

                    totalWays += check("50".toCharArray(), s);
                    for (int num = 0; num < 1000000; num++) {
                        char[] tgt = (Integer.toString(num) + "50").toCharArray();
                        totalWays += check(tgt, s);
                    }
                }
            }

            // Check for "75" pattern
            {
                char[] s = sOG.clone();
                boolean invalid = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '5');
                invalid |= s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '7';
                invalid |= (s[n - 1] == 'X' && s[n - 2] == 'X');

                if (!invalid) {
                    if (s[n - 1] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '5';
                    } else if (s[n - 2] == 'X') {
                        for (int i = 0; i < n; i++)
                            if (s[i] == 'X') s[i] = '7';
                    }
                    s[n - 1] = '5';
                    s[n - 2] = '7';

                    totalWays += check("75".toCharArray(), s);
                    for (int num = 0; num < 1000000; num++) {
                        char[] tgt = (Integer.toString(num) + "75").toCharArray();
                        totalWays += check(tgt, s);
                    }
                }
            }

            out.println(totalWays);
        }
        out.close();
    }

    static int check(char[] tgt, char[] src) {
        int n = tgt.length;
        if (src.length != n) return 0;

        char xDig = 0;
        for (int i = 0; i < n; i++)
            if (src[i] == 'X') {
                if (xDig == 0) {
                    xDig = tgt[i];
                } else {
                    if (tgt[i] != xDig) return 0;
                }
            }

        if (tgt[0] == '0') return 0;

        for (int i = 0; i < n; i++)
            if (src[i] != '_' && src[i] != 'X' && tgt[i] != src[i]) return 0;

        return 1;
    }
}
